CREATE OR REPLACE FUNCTION public.normalize_customer_phone(value text) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT CASE WHEN length(d) IN (10,11) THEN '+55'||d WHEN length(d) IN (12,13) AND left(d,2)='55' THEN '+'||d ELSE NULL END FROM (SELECT regexp_replace(coalesce(value,''),'[^0-9]','','g') d) s $$;
CREATE TABLE public.customers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), restaurant_id uuid NOT NULL REFERENCES public.restaurants(id), name text NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 100), phone text NOT NULL, address text NOT NULL DEFAULT '' CHECK(length(address)<=300), number text NOT NULL DEFAULT '' CHECK(length(number)<=30), complement text NOT NULL DEFAULT '' CHECK(length(complement)<=100), neighborhood text NOT NULL DEFAULT '' CHECK(length(neighborhood)<=100), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(restaurant_id,phone));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.customers TO authenticated;
GRANT ALL ON public.customers TO service_role;
ALTER TABLE public.customers ENABLE ROW LEVEL SECURITY;
CREATE POLICY customer_owner_access ON public.customers FOR ALL TO authenticated USING (EXISTS(SELECT 1 FROM public.restaurants r WHERE r.id=restaurant_id AND r.user_id=auth.uid()) OR public.is_super_admin(auth.uid())) WITH CHECK (EXISTS(SELECT 1 FROM public.restaurants r WHERE r.id=restaurant_id AND r.user_id=auth.uid()) OR public.is_super_admin(auth.uid()));
CREATE OR REPLACE FUNCTION public.validate_customer_record() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.phone:=public.normalize_customer_phone(NEW.phone); IF NEW.phone IS NULL THEN RAISE EXCEPTION 'Telefone inválido'; END IF; NEW.name:=trim(NEW.name); NEW.updated_at:=now(); IF TG_OP='UPDATE' AND NEW.restaurant_id<>OLD.restaurant_id THEN RAISE EXCEPTION 'Não é permitido transferir clientes entre lojas'; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_customer BEFORE INSERT OR UPDATE ON public.customers FOR EACH ROW EXECUTE FUNCTION public.validate_customer_record();
ALTER TABLE public.orders ADD COLUMN customer_id uuid REFERENCES public.customers(id), ADD COLUMN customer_address_details jsonb;
CREATE INDEX orders_customer_history ON public.orders(restaurant_id,customer_id,created_at DESC);
INSERT INTO public.customers(restaurant_id,name,phone,address,created_at) SELECT DISTINCT ON (restaurant_id,public.normalize_customer_phone(customer_phone)) restaurant_id,left(coalesce(nullif(trim(customer_name),''),'Cliente'),100),public.normalize_customer_phone(customer_phone),left(coalesce(address,''),300),created_at FROM public.orders WHERE public.normalize_customer_phone(customer_phone) IS NOT NULL ORDER BY restaurant_id,public.normalize_customer_phone(customer_phone),created_at ASC;
UPDATE public.orders o SET customer_id=c.id FROM public.customers c WHERE o.restaurant_id=c.restaurant_id AND public.normalize_customer_phone(o.customer_phone)=c.phone;
CREATE OR REPLACE FUNCTION public.link_order_customer() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p text; cid uuid; BEGIN IF TG_OP='UPDATE' AND NEW.customer_id IS NOT DISTINCT FROM OLD.customer_id AND NEW.customer_phone IS NOT DISTINCT FROM OLD.customer_phone AND NEW.restaurant_id=OLD.restaurant_id THEN RETURN NEW; END IF; IF NEW.customer_id IS NOT NULL THEN IF NOT EXISTS(SELECT 1 FROM public.customers WHERE id=NEW.customer_id AND restaurant_id=NEW.restaurant_id AND phone=public.normalize_customer_phone(NEW.customer_phone)) THEN RAISE EXCEPTION 'Cliente incompatível com a loja ou telefone'; END IF; RETURN NEW; END IF; p:=public.normalize_customer_phone(NEW.customer_phone); IF p IS NULL THEN RETURN NEW; END IF; INSERT INTO public.customers(restaurant_id,name,phone,address,number,complement,neighborhood) VALUES(NEW.restaurant_id,left(coalesce(nullif(trim(NEW.customer_name),''),'Cliente'),100),p,left(coalesce(NEW.customer_address_details->>'street',NEW.address,''),300),left(coalesce(NEW.customer_address_details->>'number',''),30),left(coalesce(NEW.customer_address_details->>'complement',''),100),left(coalesce(NEW.customer_address_details->>'neighborhood',''),100)) ON CONFLICT(restaurant_id,phone) DO NOTHING; SELECT id INTO cid FROM public.customers WHERE restaurant_id=NEW.restaurant_id AND phone=p; NEW.customer_id:=cid; RETURN NEW; END $$;
CREATE TRIGGER link_customer BEFORE INSERT OR UPDATE ON public.orders FOR EACH ROW EXECUTE FUNCTION public.link_order_customer();
CREATE OR REPLACE FUNCTION public.crm_customers(_restaurant_id uuid,_search text DEFAULT '',_registered_from date DEFAULT NULL,_registered_to date DEFAULT NULL,_last_from date DEFAULT NULL,_last_to date DEFAULT NULL,_sort text DEFAULT 'created',_page integer DEFAULT 0) RETURNS TABLE(id uuid,name text,phone text,address text,number text,complement text,neighborhood text,created_at timestamptz,purchases bigint,total_spent numeric,first_order timestamptz,last_order timestamptz,total_count bigint) LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.restaurants WHERE restaurants.id=_restaurant_id AND user_id=auth.uid()) AND NOT coalesce(public.is_super_admin(auth.uid()),false) THEN RAISE EXCEPTION 'Acesso negado' USING ERRCODE='42501'; END IF; RETURN QUERY WITH summary AS (SELECT c.*,count(o.id) purchases,coalesce(sum(o.total),0) total_spent,min(o.created_at) first_order,max(o.created_at) last_order FROM public.customers c LEFT JOIN public.orders o ON o.customer_id=c.id AND o.restaurant_id=c.restaurant_id AND o.status='completed' AND o.payment_status IN ('pago','not_required') WHERE c.restaurant_id=_restaurant_id AND (c.name ILIKE '%'||left(_search,100)||'%' OR c.phone LIKE '%'||regexp_replace(left(_search,100),'[^0-9]','','g')||'%' AND regexp_replace(_search,'[^0-9]','','g')<>'') AND (_registered_from IS NULL OR (c.created_at AT TIME ZONE 'America/Sao_Paulo')::date>=_registered_from) AND (_registered_to IS NULL OR (c.created_at AT TIME ZONE 'America/Sao_Paulo')::date<=_registered_to) GROUP BY c.id), filtered AS (SELECT * FROM summary s WHERE (_last_from IS NULL OR (s.last_order AT TIME ZONE 'America/Sao_Paulo')::date>=_last_from) AND (_last_to IS NULL OR (s.last_order AT TIME ZONE 'America/Sao_Paulo')::date<=_last_to)) SELECT f.id,f.name,f.phone,f.address,f.number,f.complement,f.neighborhood,f.created_at,f.purchases,f.total_spent,f.first_order,f.last_order,count(*) OVER() FROM filtered f ORDER BY CASE WHEN _sort='purchases' THEN f.purchases END DESC,CASE WHEN _sort='spent' THEN f.total_spent END DESC,f.created_at DESC,f.id LIMIT 25 OFFSET greatest(0,least(_page,100000))*25; END $$;
REVOKE ALL ON FUNCTION public.crm_customers(uuid,text,date,date,date,date,text,integer) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.crm_customers(uuid,text,date,date,date,date,text,integer) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.create_customer_order(_restaurant_id uuid,_name text,_phone text,_details jsonb,_items jsonb,_subtotal numeric,_delivery_fee numeric,_total numeric,_address text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE oid uuid; BEGIN IF public.normalize_customer_phone(_phone) IS NULL OR length(trim(_name)) NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'Nome e telefone válidos são obrigatórios'; END IF; IF NOT public.restaurant_accepts_orders(_restaurant_id) AND NOT EXISTS(SELECT 1 FROM public.restaurants WHERE id=_restaurant_id AND user_id=auth.uid()) AND NOT coalesce(public.is_super_admin(auth.uid()),false) THEN RAISE EXCEPTION 'Loja indisponível'; END IF; IF _details IS NOT NULL AND (jsonb_typeof(_details)<>'object' OR length(_details::text)>1500) THEN RAISE EXCEPTION 'Endereço inválido'; END IF; INSERT INTO public.orders(restaurant_id,customer_name,customer_phone,customer_address_details,items,subtotal,delivery_fee,total,address,payment_method,status,payment_status) VALUES(_restaurant_id,trim(_name),_phone,_details,_items,_subtotal,_delivery_fee,_total,_address,'pix_online','pending_payment','aguardando_pagamento') RETURNING orders.id INTO oid; RETURN oid; END $$;
REVOKE ALL ON FUNCTION public.create_customer_order(uuid,text,text,jsonb,jsonb,numeric,numeric,numeric,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.create_customer_order(uuid,text,text,jsonb,jsonb,numeric,numeric,numeric,text) TO anon,authenticated,service_role;
COMMENT ON TABLE public.customers IS 'Shared customer registry per restaurant; public phone-only profile lookup is intentionally unavailable.';